WITH ranked AS ( SELECT p.slug project,l.root_path,d.path,d.document_kind,d.title, CASE WHEN c.search_vector @@ websearch_to_tsquery('simple',$3) THEN ts_headline('simple',c.content,websearch_to_tsquery('simple',$3),'MaxWords=100,MinWords=20,MaxFragments=2,StartSel=<<,StopSel=>>,FragmentDelimiter= ... ') ELSE left(c.content,700) END excerpt,d.last_seen_at::text last_seen_at,d.last_seen_at last_seen_at_value,d.freshness_status, $5 || '; freshness=' || d.freshness_status reason, ts_rank(c.search_vector,websearch_to_tsquery('simple',$3)) score, row_number() OVER (PARTITION BY p.slug,l.root_path,d.path ORDER BY (c.search_vector @@ websearch_to_tsquery('simple',$3)) DESC, ts_rank(c.search_vector,websearch_to_tsquery('simple',$3)) DESC,c.ordinal) document_rank FROM document_chunks c JOIN document_revisions v ON v.id=c.document_revision_id AND v.is_current JOIN source_documents d ON d.id=v.source_document_id JOIN repository_locations l ON l.id=d.repository_location_id JOIN projects p ON p.id=d.project_id WHERE p.slug=$1 AND d.path=ANY($2::text[]) AND d.is_current AND d.freshness_status='current' AND ($4::text[] IS NULL OR EXISTS (SELECT 1 FROM unnest($4::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path)) ) SELECT project,root_path,path,document_kind,title,excerpt,last_seen_at,freshness_status,reason,score FROM ranked WHERE document_rank=1 ORDER BY (freshness_status='current') DESC,score DESC,last_seen_at_value DESC,path LIMIT 40
